-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.retail.evoker.augmentation.Name"] = "Icy Veins"
L["rm.retail.evoker.augmentation.Description"] = "Consigliata per Fortificazione: la priorità Vigore d'Ebano di Icy Veins. Vigore d'Ebano è uno dei pochi effetti benefici che il gioco mostra ancora agli addon in combattimento in Midnight, quindi lì il suo mantenimento funziona. Fuori combattimento: Scaglie Roventi su un bersaglio amico del gruppo che non le ha, Fiamma Vivente su un nemico. Poi Vigore d'Ebano quando manca o sotto i 4 secondi, e appena pronto a meno che Soffio degli Eoni sia pronto; Prescienza; Soffio di Fuoco; Sollevazione Terrestre; Eruzione durante Vigore d'Ebano o con due cumuli di Detonazione dell'Essenza; Assalto Azzurro; Fiamma Vivente. In combattimento un effetto benefico nascosto fa saltare solo il proprio passaggio. Promemoria: Soffio degli Eoni e Alito del Drago (li miri tu), Ago della Bilancia con Soffio di Fuoco pronto, Salto Temporale quando Soffio di Fuoco e Sollevazione Terrestre sono entrambi in recupero, più i promemoria di utilità. Prescienza e Scaglie Roventi vanno sul tuo bersaglio: la scelta dell'alleato, e del livello di potenziamento, spetta a te."
L["rm.retail.evoker.augmentation.assisted.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.evoker.augmentation.assisted.Description"] = "Il suggerimento dell'Assistente di Combattimento di Blizzard per Fortificazione, un'alternativa alla rotazione integrata consigliata Fortificazione di Icy Veins, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alza la sua priorità. Rilancia Vigore d'Ebano solo dopo che è scaduto, e attende mentre lanci o tieni premuto un incantesimo potenziato. Promemoria in combattimento per Soffio degli Eoni, Alito del Drago, Ago della Bilancia e Salto Temporale, più Sedazione, Scaglie d'Ossidiana, Benedizione del Bronzo e Sorgente della Magia come nelle altre rotazioni integrate dell'Evocatore."
L["rm.retail.evoker.devastation.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.evoker.devastation.Description"] = "Consigliata per Devastazione. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci, incanali Disintegrazione o tieni premuto un incantesimo potenziato. La scelta del livello di potenziamento spetta a te. Al suo fianco, promemoria in combattimento per Rabbia del Drago, Alito del Drago e Ago della Bilancia, Sedazione su un lancio interrompibile e Scaglie d'Ossidiana ogni volta che è pronto, e fuori combattimento Benedizione del Bronzo quando manca e Sorgente della Magia su un bersaglio amico del tuo gruppo. I lanci nemici sono nascosti in combattimento, quindi Sedazione si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi decidi tu quando usare Scaglie d'Ossidiana."
L["rm.retail.evoker.devastation.guide.Name"] = "Riferimento (SimulationCraft e Icy Veins)"
L["rm.retail.evoker.devastation.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità ottimale di Devastazione. Proc, tempi di recupero e l'ustione sul bersaglio sono nascosti in combattimento in Midnight, quindi lì non può funzionare; leggila o duplicala per sperimentare. Ingaggia con Fiamma Vivente. Comandante delle Scaglie (se conosci Disintegrazione di Massa): Impeto dell'Eternità, Soffio di Fuoco, Alito del Drago contro due o più nemici, Disintegrazione con cariche di Disintegrazione di Massa, Pira contro cinque o più, Disintegrazione, Fiamma Vivente con Surriscaldamento e Fiamme Imprevedibili, Fiamma Indomabile sotto due cumuli di Detonazione dell'Essenza, Spazzata Azzurra. Plasmafiamme: Impeto dell'Eternità, Soffio di Fuoco quando la sua ustione manca o sta per finire, Pira contro cinque o più, Disintegrazione, Alito del Drago contro quattro o più, Fiamma Indomabile, Fiamma Vivente con Surriscaldamento e Fiamme Imprevedibili, Spazzata Azzurra. Poi Assalto Azzurro in movimento, Fiamma Vivente, Assalto Azzurro. Usa i potenziamenti al livello 1 contro un solo bersaglio (Icy Veins). Promemoria: Rabbia del Drago, Ago della Bilancia durante Rabbia del Drago o con Soffio di Fuoco pronto, Alito del Drago per Comandante delle Scaglie, più i promemoria di utilità."
L["rm.retail.evoker.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.evoker.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale dell'Evocatore). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata dell'Evocatore condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.retail.evoker.preservation.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.evoker.preservation.Description"] = "Solo riferimento, disattivata per impostazione predefinita. La salute degli alleati, Eco, Regressione, Detonazione dell'Essenza e ogni tempo di recupero sono nascosti agli addon in combattimento in Midnight, Rotation Master non può scegliere chi curare e Blizzard non ha una rotazione dell'Assistente di Combattimento per i guaritori, quindi questa rotazione integrata non cura. Ti ricorda Benedizione del Bronzo e Sorgente della Magia fuori combattimento, e quando il tuo bersaglio è un nemico suggerisce danni: Soffio di Fuoco, Disintegrazione, Fiamma Vivente, e Assalto Azzurro in movimento. Promemoria di Sedazione e Scaglie d'Ossidiana come nelle altre rotazioni integrate dell'Evocatore. Le cure restano a te."
